// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;

    function setUp() public { c = new StaxLPStaking(address(new __InvMutHandleStub()), address(new __InvMutHandleStub())); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0) && newOwner != address(0));
        address deployer = c.owner();

        vm.prank(actor);
        bool ok;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }

        // General rule: ownership can only change when the CALLER IS the owner.
        // A non-owner's transferOwnership must be a no-op (revert, owner unchanged).
        if (actor != deployer) {
            assertTrue(c.owner() == deployer, "non-owner must not change ownership");
        } else {
            assertTrue(c.owner() == newOwner);
        }
    }
}
